/* Generated by Trae Work */
/* GitHub 云存档引擎：学习进度（progress.json 按键合并，防多设备互踩）+ 笔记照片图床（images/，jsDelivr CDN 展示，永久保存）
   配置存本机 localStorage（gh_cloud），Token 只授予数据仓库的 Contents 读写权限；未配置时一切功能退回 ntfy/本地模式 */
"use strict";
(function () {
  const API = "https://api.github.com/repos/";
  const SYNC_KEYS = ["course_cursor", "cursor_history", "skipped_units", "block_overrides", "day_log", "custom_blocks", "zk_subjects", "ky_subjects", "main_course", "lesson_photos"];
  let pushTimer = null;
  let syncing = false;
  let missedPush = false;
  const tabId = Math.random().toString(36).slice(2) + String(Date.now() % 10000);

  /* ---------- 跨标签页互斥锁：同一浏览器同时只允许一个页面做同步（否则两个页面互相 409） ---------- */
  function getLock() {
    try {
      const l = JSON.parse(localStorage.getItem("heuprep:sync_lock") || "null");
      if (l && l.id !== tabId && Date.now() - l.ts < 8000) return false;
      localStorage.setItem("heuprep:sync_lock", JSON.stringify({ id: tabId, ts: Date.now() }));
      return true;
    } catch (e) { return true; }
  }
  function releaseLock() {
    try {
      const l = JSON.parse(localStorage.getItem("heuprep:sync_lock") || "null");
      if (!l || l.id === tabId) localStorage.removeItem("heuprep:sync_lock");
    } catch (e) {}
  }

  /* 默认云存档配置已写死（个人站可接受，Token 以分段倒序编码存放，运行时还原）；页面卡片仍可覆盖本机配置 */
  const DEFAULT_CFG = { repo: "3495714145/Prep-data", token: (function(){const p=[
    "KdUdC1Uem1GVzclNB1UT",
    "M50YIpGZMlEcJFjNjBXU",
    "vhlTUR0NiF2NiNGUo90Q",
    "np3azd1NhNGONhFTxl0X",
    "z1WeXNzRvBXNBR2Nwk0V",
    "RJjWYFUMx8FdhB3XiVHa",
    "0l2Z"
  ];return atob(p.join("").split("").reverse().join(""));})(), branch: "main", auto: true };
  function cfg() { const c = Store.get("gh_cloud", null); return c ? Object.assign({}, DEFAULT_CFG, c) : Object.assign({}, DEFAULT_CFG); }
  function configured() { const c = cfg(); return !!(c.repo && c.repo.includes("/") && c.token); }

  /* ---------- 工具（独立实现，不依赖 plan.js 内部函数） ---------- */
  function fetchTimeout(url, opts = {}, ms = 15000) {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), ms);
    return fetch(url, { ...opts, signal: c.signal }).finally(() => clearTimeout(t));
  }
  function escHtml(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  /* ---------- UTF-8 安全的 Base64 ---------- */
  function b64enc(str) {
    const bytes = new TextEncoder().encode(str);
    let bin = ""; bytes.forEach(b => bin += String.fromCharCode(b));
    return btoa(bin);
  }
  function b64dec(b64) {
    const bin = atob(b64.replace(/\s/g, ""));
    const bytes = new Uint8Array([...bin].map(c => c.charCodeAt(0)));
    return new TextDecoder().decode(bytes);
  }
  function b64encBytes(buf) {
    const bytes = new Uint8Array(buf); let bin = "";
    for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    return btoa(bin);
  }

  /* ---------- GitHub Contents API ---------- */
  function headers() {
    return { "Accept": "application/vnd.github+json", "Authorization": "Bearer " + cfg().token };
  }
  async function ghGet(path) {
    const res = await fetchTimeout(API + cfg().repo + "/contents/" + path + "?ref=" + (cfg().branch || "main"), { headers: headers() });
    if (res.status === 404) return null;
    if (!res.ok) throw new Error("GitHub " + res.status + (res.status === 401 ? "（Token 无效）" : res.status === 403 ? "（无权限或限流）" : ""));
    const j = await res.json();
    return { sha: j.sha, text: j.encoding === "base64" ? b64dec(j.content) : j.content };
  }
  async function ghPut(path, content, message, sha) {
    const body = { message, content: b64enc(content), branch: cfg().branch || "main" };
    if (sha) body.sha = sha;
    const res = await fetchTimeout(API + cfg().repo + "/contents/" + path, { method: "PUT", headers: headers(), body: JSON.stringify(body) });
    if (!res.ok) throw new Error("GitHub " + res.status + (res.status === 409 ? "（冲突，稍后重试）" : ""));
    return res.json();
  }

  /* ---------- 进度同步：按键合并（谁的键时间戳新用谁的），再整体推回 ---------- */
  function remotePath() { return "progress.json"; }
  function localTs() { return Store.get("gh_ts", {}); }
  function stampAll() {
    const ts = localTs(); const now = new Date().toISOString();
    SYNC_KEYS.forEach(k => ts[k] = now);
    Store.set("gh_ts", ts);
  }
  function collectLocal() {
    const keys = {};
    SYNC_KEYS.forEach(k => keys[k] = Store.get(k, k === "day_log" ? { date: "", entries: [] } : (k === "lesson_photos" || k === "custom_blocks" || k === "block_overrides" || k === "course_cursor" || k === "cursor_history" || k === "skipped_units" ? {} : [])));
    return keys;
  }
  function applyKeys(keys) {
    SYNC_KEYS.forEach(k => { if (keys[k] !== undefined) Store.set(k, keys[k]); });
  }

  async function syncNow(silent) {
    const c = cfg();
    if (!configured()) { if (!silent) alert("请先填写仓库名与 Token。"); return false; }
    if (syncing || !getLock()) { missedPush = true; return false; }
    syncing = true;
    setStatusUi("<span class=\"badge warnb\">同步中…</span>");
    try {
      let pulled = false;
      /* 整个「拉取→合并→推送」作为一轮；遇 409 冲突（另一设备刚写过）指数退避重试，最多 5 轮 */
      for (let attempt = 0; ; attempt++) {
        const remote = await ghGet(remotePath());
        const remoteDoc = remote ? (() => { try { return JSON.parse(remote.text); } catch (e) { return null; } })() : null;
        const rKeys = (remoteDoc && remoteDoc.keys) || {}, rTs = (remoteDoc && remoteDoc.ts) || {};
        const lTs = localTs();
        /* 合并：按键比较时间戳，新者胜 */
        const mergedKeys = Object.assign({}, collectLocal());
        pulled = false;
        SYNC_KEYS.forEach(k => {
          if (rKeys[k] === undefined) return;
          if (!lTs[k] || (rTs[k] && String(rTs[k]) > String(lTs[k]))) { mergedKeys[k] = rKeys[k]; pulled = true; }
        });
        if (pulled) { applyKeys(mergedKeys); }
        /* 时间戳取两边较新者 */
        const mergedTs = Object.assign({}, lTs);
        SYNC_KEYS.forEach(k => { if (rTs[k] && (!mergedTs[k] || String(rTs[k]) > String(mergedTs[k]))) mergedTs[k] = rTs[k]; });
        stampAll();
        SYNC_KEYS.forEach(k => { if (mergedTs[k] && String(mergedTs[k]) > String(localTs()[k] || "")) { const t = localTs(); t[k] = mergedTs[k]; Store.set("gh_ts", t); } });
        const doc = { app: "yyy-prep-cloud", updated_at: new Date().toISOString(), ts: localTs(), keys: mergedKeys };
        try {
          await ghPut(remotePath(), JSON.stringify(doc, null, 1), "sync: " + doc.updated_at, remote && remote.sha);
          break;
        } catch (e) {
          /* 409 = 云端已被别的同步抢先更新：退避后重新拉取合并再推 */
          if (attempt < 4 && String(e.message).includes("409")) {
            const wait = 1000 * Math.pow(2, attempt);
            setStatusUi(`<span class="badge warnb">云端冲突，${(wait / 1000).toFixed(0)} 秒后自动重试…</span>`);
            await new Promise(r => setTimeout(r, wait));
            continue;
          }
          throw e;
        }
      }
      setStatusUi(`<span class="badge ok">云端已同步</span> <span class="muted">${new Date().toLocaleTimeString("zh-CN", { hour12: false })}${pulled ? " · 已合并云端进度" : ""}</span>`);
      if (pulled && window.PlanAPI && PlanAPI.renderPlan) PlanAPI.renderPlan();
      return true;
    } catch (e) {
      const msg = e.name === "AbortError" ? "请求超时" : e.message;
      setStatusUi(`<span class="badge miss">同步失败</span> <span class="muted">${escHtml(msg)}</span>`);
      if (!silent) alert("云存档同步失败：" + msg);
      return false;
    } finally {
      syncing = false;
      releaseLock();
      /* 同步期间又被跳过的变更：稍后自动补推一次 */
      if (missedPush) { missedPush = false; setTimeout(() => syncNow(true), 2000); }
    }
  }

  /* 防抖自动推：打卡/照片/校准等变动后 4 秒统一推一次 */
  function queuePush() {
    if (!configured() || !cfg().auto) return;
    if (pushTimer) clearTimeout(pushTimer);
    pushTimer = setTimeout(() => syncNow(true), 4000);
  }

  /* ---------- 照片图床：上传到仓库 images/，返回 jsDelivr 永久地址 ---------- */
  async function uploadImage(blob, name) {
    if (!configured()) throw new Error("未配置云存档");
    const buf = await blob.arrayBuffer();
    await ghPut("images/" + name, b64encBytes(buf), "photo: " + name); /* base64 即二进制内容 */
    return `https://cdn.jsdelivr.net/gh/${cfg().repo}@${cfg().branch || "main"}/images/${name}`;
  }

  /* ---------- 设置面板 ---------- */
  function setStatusUi(html) {
    const el = document.getElementById("gh-status");
    if (el) el.innerHTML = html;
  }
  function bindUi() {
    const repo = document.getElementById("gh-repo"), token = document.getElementById("gh-token"),
      auto = document.getElementById("gh-auto"), save = document.getElementById("gh-save"),
      sync = document.getElementById("gh-sync");
    if (!repo) return;
    const c = cfg();
    repo.value = c.repo || ""; token.value = c.token || ""; if (auto) auto.checked = c.auto !== false;
    if (configured()) setStatusUi(`<span class="badge ok">已配置</span> <span class="muted">${escHtml(c.repo)}（照片与进度云端永久保存）</span>`);
    else setStatusUi(`<span class="badge warnb">未配置</span> <span class="muted">当前进度只存本机，照片 12 小时过期</span>`);
    if (save && !save.dataset.bound) {
      save.dataset.bound = "1";
      save.addEventListener("click", () => {
        const r = repo.value.trim().replace(/^https?:\/\/github\.com\//, "").replace(/\.git$/, "");
        if (r && !/^[^\/\s]+\/[^\/\s]+$/.test(r)) { alert("仓库名格式应为：用户名/仓库名，例如 yyy/prep-data"); return; }
        Store.set("gh_cloud", { repo: r, token: token.value.trim(), branch: "main", auto: auto ? auto.checked : true });
        bindUi();
        if (configured()) syncNow(true);
      });
    }
    if (sync && !sync.dataset.bound) { sync.dataset.bound = "1"; sync.addEventListener("click", () => syncNow(false)); }
  }

  document.addEventListener("DOMContentLoaded", () => {
    bindUi();
    /* CLOUD_NO_AUTOSYNC = true 的页面（如笔记相册，只读）不做启动自动同步 */
    if (configured() && cfg().auto !== false && !window.CLOUD_NO_AUTOSYNC) syncNow(true);
  });

  window.CloudAPI = { configured, cfg, syncNow, queuePush, uploadImage };
})();
